def transform(grid):
    g = np.array(grid)
    bg = background(g)
    objs = objects(g, bg=bg, multicolour=True)
    from collections import Counter
    cnt = Counter(g[g != bg].tolist())
    struct = max(cnt, key=cnt.get)  # structural colour = most common non-bg colour
    shapes = [o for o in objs if o["size"] > 1 and any(g[y][x] == struct for y, x in o["cells"])]
    shape_cells = set()
    for s in shapes:
        shape_cells.update(s["cells"])
    # scattered markers: every non-bg cell not part of a shape
    targets = {}
    for y in range(g.shape[0]):
        for x in range(g.shape[1]):
            if g[y][x] != bg and (y, x) not in shape_cells:
                targets[(y, x)] = int(g[y][x])
    out = g.copy()
    H, W = out.shape
    for s in shapes:
        cells = [(y, x, int(g[y][x])) for y, x in s["cells"]]
        # stage: erase the shape from its original position
        for y, x, c in cells:
            out[y][x] = bg
        emit(out, "Erase the shape at its original location; it will be redrawn on its marker legend.")
        found = False
        for t in range(8):
            tc = []
            for y, x, c in cells:
                yy, xx = y, x
                if t & 1: yy = -yy
                if t & 2: xx = -xx
                if t & 4: yy, xx = xx, yy
                tc.append((yy, xx, c))
            marks = [m for m in tc if m[2] != struct]
            if not marks:
                continue
            my, mx, mc = marks[0]
            for (ty, tx), col in targets.items():
                if col != mc:
                    continue
                dy, dx = ty - my, tx - mx
                if all(targets.get((y + dy, x + dx)) == c for y, x, c in marks):
                    for y, x, c in tc:
                        yy, xx = y + dy, x + dx
                        if 0 <= yy < H and 0 <= xx < W:
                            out[yy][xx] = c
                    found = True
                    break
            if found:
                break
        emit(out, "Rotate/reflect the shape so its coloured markers coincide with the scattered markers of the same colours, and stamp it there.")
    emit(out, "All shapes relocated onto their marker legends.")
    return out
